#include <bits/stdc++.h>
using namespace std;struct A{array<unsigned char,14>m;int center;uint32_t ua;};vector<A>as[16];unordered_map<uint64_t,uint32_t>bad;int idx[16][16];array<int,16>pm;ofstream failures;long long pairsChecked=0,failed=0,pbcount[16]{};
uint64_t key(){uint64_t k=0;for(int i=0;i<16;i++)k|=uint64_t(pm[i])<<(4*i);return k;}
void assess(int center){pbcount[center]++;auto k=key();uint32_t bm=bad[k];for(int a=0;a<16;a++)if(pm[a]>a&&__builtin_popcount(unsigned(a^pm[a]))==1)bm|=1u<<idx[a][pm[a]];for(auto&a:as[center]){pairsChecked++;if(!(a.ua&~bm)){failed++;for(auto z:a.m)failures.put(char(z));for(int z=0;z<16;z++)failures.put(char(pm[z]));failures.put(char(center));}}}
void gen(unsigned m,int center){if(!m){assess(center);return;}int a=__builtin_ctz(m);m^=1u<<a;for(int b=a+1;b<16;b++)if(m>>b&1){pm[a]=b;pm[b]=a;gen(m^(1u<<b),center);}}
int main(){int e=0;for(int a=0;a<16;a++)for(int b=a+1;b<16;b++)if(__builtin_popcount(unsigned(a^b))==1)idx[a][b]=idx[b][a]=e++;ifstream ai("eight_ep0_q4_star_A.bin",ios::binary);unsigned char raw[19];int n=0;while(ai.read((char*)raw,19)){A a;copy(raw,raw+14,a.m.begin());a.center=raw[14];a.ua=0;for(int j=0;j<4;j++)a.ua|=uint32_t(raw[15+j])<<(8*j);as[a.center].push_back(a);n++;}assert(n==444);ifstream bi("eight_ep0_q4_PB_bad_optional.txt");uint64_t k;uint32_t mask;while(bi>>k>>mask)bad[k]=mask;assert(bad.size()==16816);failures.open("eight_ep0_q4_star_joint_failures.bin",ios::binary);for(int center:{1,2,4,8}){assert(as[center].size()==111);pm[0]=center;pm[center]=0;gen(65534u&~(1u<<center),center);vector<uint64_t>extra;for(auto[k,b]:bad)if(b>>idx[0][center]&1u)extra.push_back(k);assert(extra.size()==714);for(auto k:extra){for(int i=0;i<16;i++)pm[i]=(k>>(4*i))&15;assert(pm[0]!=center);assess(center);}cerr<<center<<" PB"<<pbcount[center]<<" pairs"<<pairsChecked<<" failed"<<failed<<"\n";}cout<<"{\"star_A_matchings\":444,\"PB_candidates_per_center\":135849,\"A_B_pairs_checked\":"<<pairsChecked<<",\"residual_pairs\":"<<failed<<"}\n";}
